SELECT billPayId, payeeDate, payeeOrgId, payeeOrgName, billId, billNum, billOrgId, billOrgName, billDate, patientId, patientName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT billPayId, DATE_FORMAT(payeeDate, '%Y-%m-%d') AS payeeDate, payeeOrgId, payeeOrgName, billId, billNum, billOrgId, billOrgName, DATE_FORMAT(billDate, '%Y-%m-%d') AS billDate, patientId, patientName, pinyin_name AS pinyinName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT bbp.bill_pay_id AS billPayId, bbp.payee_date AS payeeDate, bbp.org_id AS payeeOrgId, bo.abbreviation AS payeeOrgName, bbp.bill_id AS billId, bb.bill_num AS billNum, bbp.org_id AS billOrgId, bo.abbreviation as billOrgName, bb.bill_date AS billDate, btp.patientId, btp.patientName, btp.patientMobile, btp.pinyin_name, btp.regDentistId, btp.regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS totalReceivedAmount, bbp.received_amount AS receivedAmount, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id LEFT JOIN base_organization bo on bbp.org_id = bo.org_id LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.org_id, btp.treatment_id, btp.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.org_id, btp.treatment_id, btp.patient_id, bp.`name`, bp.mobile, bp.pinyin_name, btp.registered_dentist_id, be.employee_name ) btp ON bbp.treatment_id = btp.treatment_id ) bbp, ( SELECT bb.org_id, bb.bill_id, bb.bill_date FROM base_bill bb
AND bb.bill_date IS NOT NULL AND bb.bill_num IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) <= #{query.endDate}
GROUP BY bb.org_id, bb.bill_id, bb.bill_date ) bb
AND bbp.billId = bb.bill_id AND bbp.payeeDate = bb.bill_date AND bbp.billOrgId = bb.org_id
) bbp
AND concat(IFNULL(bbp.patientName, ''),IFNULL(bbp.pinyinName, ''), IFNULL(bbp.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND bbp.billNum LIKE concat('%', #{query.billNum}, '%')
AND bbp.payeeDate >= #{query.chargeStartDate}
AND bbp.payeeDate <= #{query.chargeEndDate}
order by bbp.payeeDate, bbp.billNum desc

